// nf-core modules test trgt
nextflow_process {

    name "Test Process TRGT_GENOTYPE"
    script "../main.nf"
    config './nextflow.config'
    process "TRGT_GENOTYPE"

    tag "modules"
    tag "modules_nfcore"
    tag "trgt"
    tag "trgt/genotype"
    tag "samtools/faidx"
    tag "gunzip"

    setup {
        run("GUNZIP"){
            script "../../../gunzip/main.nf"
            process {
                """
                input[0] = [
                    [ id : 'chr22' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/genome/chr22_chr22_KI270734v1_random/sequence/genome.fa.gz', checkIfExists: true)
                ]
            """
            }
        }
        run("SAMTOOLS_FAIDX"){
            script "../../../samtools/faidx/main.nf"
            process {
                """
                input[0] = GUNZIP.out.gunzip
                    .combine(channel.of([[]]))
                input[1] = false
                """
            }
        }
    }

    test("homo sapiens - [bam,bai,XX], [fa,fai], bed") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/test.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/test.sorted.bam.bai', checkIfExists: true),
                    [],
                    [],
                    'XX'
                ]
                input[1] = GUNZIP.out.gunzip
                input[2] = SAMTOOLS_FAIDX.out.fai
                input[3] = Channel.of('chr22\t18890357\t18890451\tID=TEST;MOTIFS=AT;STRUC=(AT)n')
                            .collectFile(name : 'repeats.bed', newLine: false)
                            .map { file -> [ [ id : 'chr22' ], file ] }
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out, readsMD5Keys: ["bam"], variantsMD5Keys: ["vcf"])).match() })
        }
    }

    test("homo sapiens - [bam,bai,fail_reads_bam,fail_reads_bai,XX], [fa,fai], bed") {

        when {
            params {
                module_args = '--sample-name test'
            }
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/test.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/test.sorted.bam.bai', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/test.fail_reads.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/test.fail_reads.sorted.bam.bai', checkIfExists: true),
                    'XX'
                ]
                input[1] = GUNZIP.out.gunzip
                input[2] = SAMTOOLS_FAIDX.out.fai
                input[3] = Channel.of('chr22\\t18890357\\t18890451\\tID=TEST;MOTIFS=AT;STRUC=(AT)n')
                            .collectFile(name : 'repeats.bed', newLine: false)
                            .map { file -> [ [ id : 'chr22' ], file ] }
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out, readsMD5Keys: ["bam"], variantsMD5Keys: ["vcf"])).match() }
            )
        }
    }

    test("homo sapiens - [bam,bai,[]], [fa,fai], bed") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/test.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/test.sorted.bam.bai', checkIfExists: true),
                    [],
                    [],
                    []
                ]
                input[1] = GUNZIP.out.gunzip
                input[2] = SAMTOOLS_FAIDX.out.fai
                input[3] = Channel.of('chr22\t18890357\t18890451\tID=TEST;MOTIFS=AT;STRUC=(AT)n')
                            .collectFile(name : 'repeats.bed', newLine: false)
                            .map { file -> [ [ id : 'chr22' ], file ] }
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out, readsMD5Keys: ["bam"], variantsMD5Keys: ["vcf"])).match() }
            )
        }

    }

    test("homo sapiens - [bam,bai,XX], [fa,fai], bed - stub") {
        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/test.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/test.sorted.bam.bai', checkIfExists: true),
                    [],
                    [],
                    'XX'
                ]
                input[1] = GUNZIP.out.gunzip
                input[2] = SAMTOOLS_FAIDX.out.fai
                input[3] = Channel.of('chr22\t18890357\t18890451\tID=TEST;MOTIFS=AT;STRUC=(AT)n')
                                .collectFile(name : 'repeats.bed', newLine: false)
                                .map { file -> [ [ id : 'chr22' ], file ] }
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }


    }

    test("homo sapiens - [bam,bai,[]], [fa,fai], bed - stub") {
        options "-stub"
        when {
            process {
                """
                input[0] = [
                    [ id:'test' ],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/test.sorted.bam', checkIfExists: true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/pacbio/bam/test.sorted.bam.bai', checkIfExists: true),
                    [],
                    [],
                    []
                ]
                input[1] = GUNZIP.out.gunzip
                input[2] = SAMTOOLS_FAIDX.out.fai
                input[3] = Channel.of('chr22\t18890357\t18890451\tID=TEST;MOTIFS=AT;STRUC=(AT)n')
                            .collectFile(name : 'repeats.bed', newLine: false)
                            .map { file -> [ [ id : 'chr22' ], file ] }
                """
            }
        }

        then {
            assert process.success
            assertAll(
                { assert snapshot(sanitizeOutput(process.out)).match() }
            )
        }

    }
}

